import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"0045 — An external standard service is a sealed slot with a protocol tag","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0045-external-standard-services-are-sealed-slots.md","filePath":"spec/decisions/0045-external-standard-services-are-sealed-slots.md"}'),r={name:"spec/decisions/0045-external-standard-services-are-sealed-slots.md"};function i(n,e,c,d,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="_0045-—-an-external-standard-service-is-a-sealed-slot-with-a-protocol-tag" tabindex="-1">0045 — An external standard service is a sealed slot with a protocol tag <a class="header-anchor" href="#_0045-—-an-external-standard-service-is-a-sealed-slot-with-a-protocol-tag" aria-label="Permalink to &quot;0045 — An external standard service is a sealed slot with a protocol tag&quot;">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-08-23</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./0043-forms-target-popular-vendor-locked-primitives.html">Decision 0043</a> split the world in two: vendor-locked categories become Form Families, and categories with a de-facto standard API are integrated. It promised the integration contract as its own change without fixing its shape.</p><p>Three shapes were available. A <strong>resource shape</strong> — an <code>ExternalService</code> Resource holding the endpoint — puts a URL in portable desired state and walks straight into the authority boundary: endpoints imply accounts, accounts imply credentials, and the repository has spent its whole life keeping both out of portable state. A <strong>binding shape</strong> — reusing the typed Binding contract — misstates the relationship: a Binding targets an in-space Resource providing a Takoform Interface, pins its uid and exact FormRef, and participates in relation lifecycle; an external Postgres has none of those and pretending otherwise would hollow out what a Binding&#39;s pin means. The <strong>sealed-slot shape</strong> already exists: <code>requiredSensitiveVars</code> declares, in portable state, only the NAME of a value the host supplies at runtime.</p><p>An external standard service is exactly that, plus one fact the name alone cannot carry: which protocol the supplied material must speak.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>An external standard service is declared as a sealed slot with a protocol tag</strong>: portable state carries <code>{name, service: {apiVersion, protocol}}</code> and nothing else; the host or operator satisfies the slot with connection material for a service speaking that protocol; the projection into the consumer&#39;s runtime namespace is fixed per protocol so consumer code stays portable. The normative contract is <a href="./../standard-services/"><code>../standard-services/README.md</code></a> with the closed vocabulary in <code>standard-service-ref-v1alpha1.schema.json</code> (<code>s3-compatible</code>, <code>postgresql</code>, <code>redis</code>, <code>smtp</code>).</p><p>The contract deliberately grants no lifecycle authority over the external service and never verifies the wired service&#39;s protocol conformance — the host vouches for what it wires. Widening the protocol vocabulary is a reviewed spec change held to decision 0043&#39;s test.</p><p>The published v1beta1 schemas are untouched: they are frozen identities, so families minted from now on carry the declaration from birth, and the Edge family adopts it when a graduation mints its next identities (<a href="./0037-immutability-begins-at-stable.html">decision 0037</a>).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>A container revision can reach the team&#39;s Postgres and an S3-compatible bucket without either appearing in state, without Takoform growing a database Form it swore off, and without a Binding pretending an external service has a uid. The first family that embeds the declaration brings the executable conformance for it; until then the contract&#39;s own document says no host can claim measured support.</p>',12)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
